import{_ as e,c as a,o as l,a4 as p}from"./chunks/framework.NcOuGTBf.js";const h=JSON.parse('{"title":"初识Webpack","description":"","frontmatter":{},"headers":[],"relativePath":"frontEnd/webpack/index.md","filePath":"frontEnd/webpack/index.md"}'),o={name:"frontEnd/webpack/index.md"},t=p('<h1 id="初识webpack" tabindex="-1">初识Webpack <a class="header-anchor" href="#初识webpack" aria-label="Permalink to &quot;初识Webpack&quot;">​</a></h1><h2 id="_1、什么是webpack" tabindex="-1">1、什么是webpack <a class="header-anchor" href="#_1、什么是webpack" aria-label="Permalink to &quot;1、什么是webpack&quot;">​</a></h2><p>webpack是一个用于js的静态模块化打包工具，通过loader转换文件，通过plugin注入钩子 ，最后输出由多个模块组合成的静态资源。</p><p>webpack的四个核心概念：</p><ul><li>入口(entry)</li><li>输出(output)</li><li>loader</li><li>插件(plugins)</li></ul><h2 id="_2、loader的基本原理" tabindex="-1">2、loader的基本原理 <a class="header-anchor" href="#_2、loader的基本原理" aria-label="Permalink to &quot;2、loader的基本原理&quot;">​</a></h2><p>loader被翻译为<code>加载器</code></p><p>webpack本身只能解析js和json文件，为了能够让webpack解析其他形式文件的能力，比如css、image、less、scss、vue等文件</p><p>手写loader:</p><p>loader通常导出一个函数，在配置时可以给函数传参。loader通过配置schema.json配置文件，约束传入的参数。</p><p>导出的函数默认接收webpack传递的匹配的文件内容，而后可对文件内容进行修改返回。</p><ul><li>比如在每个文件前面添加署名注释，即可在文件中添加前缀返回即可</li><li>比如将css文件内容添加到style标签中，再返回即可</li></ul><h2 id="_3、plugin的基本原理" tabindex="-1">3、plugin的基本原理 <a class="header-anchor" href="#_3、plugin的基本原理" aria-label="Permalink to &quot;3、plugin的基本原理&quot;">​</a></h2><p>plugin给webpack提供扩展，让webpack更灵活。在webpack运行过程中会触发一系列的钩子函数，plugin可以监听这些事件，从而在特定的时间改变webpack输出的结果。</p>',14),c=[t];function i(r,n,s,d,_,b){return l(),a("div",null,c)}const k=e(o,[["render",i]]);export{h as __pageData,k as default};
